package com.varnalabs.mobile;
class Range58Test {public static void main(String[] args){String[] requests={null,"bytes=0-","bytes=5-9","bytes=-3","bytes=7-100"};long[][] expected={{0,9},{0,9},{5,9},{7,9},{7,9}};for(int i=0;i<requests.length;i++){long[] result=MediaRange58.parse(requests[i],10);if(result[0]!=expected[i][0]||result[1]!=expected[i][1])throw new RuntimeException();}for(String bad:new String[]{"bytes=10-","bytes=8-4","bytes=-0","bytes=1-2,4-5"}){try{MediaRange58.parse(bad,10);throw new RuntimeException("Accepted bad range");}catch(IllegalArgumentException ok){}}System.out.println("PASS58 actual Java media ranges: full, open-ended, suffix, bounds and unsatisfiable/multi-range rejection");}}
